plugins {
    id "com.android.application"
    id "kotlin-android"
    // The Flutter Gradle Plugin must be applied after the Android and Kotlin Gradle plugins.
    id "dev.flutter.flutter-gradle-plugin"
}

// Where keystore is locally stored.
def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file('key.properties')
if (keystorePropertiesFile.exists()) {
    keystorePropertiesFile.withReader('UTF-8') { reader ->
        keystoreProperties.load(reader)
    }
}

android {
    // ----- BEGIN flavorDimensions (autogenerated by flutter_flavorizr) -----
    flavorDimensions += "flavor-type"

    productFlavors {
        ni {
            dimension "flavor-type"
            applicationId "wemove.app.bipu"
            resValue "string", "app_name", "UmweltNAVI Niedersachsen"
        }
        sh {
            dimension "flavor-type"
            applicationId "de.wemove.umweltnavi.sh"
            resValue "string", "app_name", "UmweltNAVI Schleswig-Holstein"
        }
        rp {
            dimension "flavor-type"
            applicationId "de.wemove.umweltnavi.rp"
            resValue "string", "app_name", "UmweltNAVI Rheinland-Pfalz"
        }
    }
    // ----- END flavorDimensions (autogenerated by flutter_flavorizr) -----

    namespace = "de.wemove.umweltnavi"
    compileSdk = flutter.compileSdkVersion
    ndkVersion = flutter.ndkVersion

    compileOptions {
        // Added for flutter_local_notifications.
        coreLibraryDesugaringEnabled true

        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
    }

    kotlinOptions {
        jvmTarget = JavaVersion.VERSION_11
    }

    sourceSets {
        main.java.srcDirs += 'src/main/kotlin'
    }

    defaultConfig {
        applicationId = "de.wemove.umweltnavi"
        minSdk = flutter.minSdkVersion
        targetSdk = flutter.targetSdkVersion
        versionCode = flutter.versionCode
        versionName = flutter.versionName
        multiDexEnabled = true

        // Testframework Patrol configs.
        testInstrumentationRunner "pl.leancode.patrol.PatrolJUnitRunner"
        testInstrumentationRunnerArguments clearPackageData: "false"
    }

    signingConfigs {
        release {
            keyAlias keystoreProperties['keyAlias']
            keyPassword keystoreProperties['keyPassword']
            storeFile file(keystoreProperties['storeFile'])
            storePassword keystoreProperties['storePassword']
        }
    }
